/**
 * Classifies a decoded tessellated triangle as a point, line or triangle.
 *
 * <p>Degenerate triangles are collapsed to the line segment formed by their distinct vertices.
 * The edge flags are updated at the same time so that the line keeps the "part of the original
 * shape" information of the edge that is actually retained.
 */
void resolveTriangleType(ShapeField.DecodedTriangle triangle) {
  if (triangle.aX == triangle.bX && triangle.aY == triangle.bY) {
    if (triangle.aX == triangle.cX && triangle.aY == triangle.cY) {
      triangle.type = ShapeField.DecodedTriangle.TYPE.POINT;
    } else {
      final boolean bc = triangle.bc;
      triangle.bX = triangle.cX;
      triangle.bY = triangle.cY;
      triangle.cX = triangle.aX;
      triangle.cY = triangle.aY;
      // The collapsed edge is ab.  The retained line is made up of the (coincident) bc and ca
      // edges, so it is part of the original shape if either of them is.
      triangle.ab = triangle.ca || bc;
      triangle.type = ShapeField.DecodedTriangle.TYPE.LINE;
    }
  } else if (triangle.aX == triangle.cX && triangle.aY == triangle.cY) {
    // The collapsed edge is ca.  The retained line is ab (coincident with bc).
    triangle.ab = triangle.ab || triangle.bc;
    triangle.type = ShapeField.DecodedTriangle.TYPE.LINE;
  } else if (triangle.bX == triangle.cX && triangle.bY == triangle.cY) {
    // The collapsed edge is bc.  The retained line is ab (coincident with ca).
    triangle.ab = triangle.ab || triangle.ca;
    triangle.cX = triangle.aX;
    triangle.cY = triangle.aY;
    triangle.type = ShapeField.DecodedTriangle.TYPE.LINE;
  } else {
    triangle.type = ShapeField.DecodedTriangle.TYPE.TRIANGLE;
  }
}

