 *
 * <p>Degenerate triangles are collapsed to the line segment formed by their distinct vertices.
 * The edge flags are updated at the same time so that the line keeps the "part of the original
 * shape" information of the edge that is actually retained.
 */
void resolveTriangleType(ShapeField.DecodedTriangle triangle) {
  if (triangle.aX == triangle.bX && triangle.aY == triangle.bY) {
    if (triangle.aX == triangle.cX && triangle.aY == triangle.cY) {
      triangle.type = ShapeField.DecodedTriangle.TYPE.POINT;
    } else {
      final boolean bc = triangle.bc;
      triangle.bX = triangle.cX;
      triangle.bY = triangle.cY;
      triangle.cX = triangle.aX;
      triangle.cY = triangle.aY;
